use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::{Command,Stdio}};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new("/tmp/zopro-ready-c7a");assert_eq!(read(r.join("native/result.json"))["status"],"complete");let c=r.join("context");fs::create_dir(&c).unwrap();fs::create_dir(c.join("basis")).unwrap();
 let mut pins=BTreeMap::<String,String>::new();
 for(mode,name)in[("accepted","ready-accepted"),("diagnostic","ready-diagnostic")]{let a=read(r.join(format!("native/{mode}/artifacts.json")));assert_eq!(hash(a["binary"].as_str().unwrap()),a["binary_sha256"].as_str().unwrap());fs::copy(a["binary"].as_str().unwrap(),c.join(name)).unwrap();pins.insert(format!("/usr/local/bin/{name}"),hash(c.join(name)));for(p,h)in a["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}}
 for name in ["adapter","runner"]{let path=r.join(name);let target=c.join(format!("ready-{name}"));fs::copy(path,&target).unwrap();pins.insert(format!("/usr/local/bin/ready-{name}"),hash(target));}
 fs::copy("/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask",c.join("ready-xtask")).unwrap();pins.insert("/usr/local/bin/ready-xtask".into(),hash(c.join("ready-xtask")));
 let a=read("/tmp/zopro-grouping-module/production-source-manifest.json");let old=read("/tmp/zopro-ready-arithmetic/perf-plan.json");let mut cases=BTreeMap::new();for shape in["1x2","8x2"]{let mut case=old["cases"].as_array().unwrap().iter().find(|x|x["shape"]==shape&&x["workers"]==32).unwrap().clone();let image=Path::new(case["image"].as_str().unwrap());let basename=image.file_name().unwrap().to_str().unwrap();fs::copy(image,c.join("basis").join(basename)).unwrap();pins.insert(format!("/ready-basis/{basename}"),hash(image));case["image"]=json!(format!("/ready-basis/{basename}"));case["request"]=json!(format!("/fixtures/transfer-{shape}.json"));let local=Path::new("/home/ubuntu/src/zk-tools/zopro/tools/zolana/fixtures").join(format!("transfer-{shape}.json"));pins.insert(case["request"].as_str().unwrap().into(),hash(local));cases.insert(shape,case);}
 let previous=read("/tmp/zopro-latest-c7a/context/current-aws.json");pins.insert("/usr/local/bin/aeglos-ablation".into(),previous["binaries"]["aeglos-default"]["sha256"].as_str().unwrap().into());pins.insert("/usr/local/bin/gnark-verify".into(),hash("/tmp/zopro-gnark-verify/verify"));pins.insert("/manifest/zopro-keys.lock".into(),hash("/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock"));fs::copy("/tmp/zopro-gnark-verify/verify",c.join("gnark-verify")).unwrap();fs::copy("/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock",c.join("zopro-keys.lock")).unwrap();
 let lock=read("/home/ubuntu/src/zk-tools/zopro/tools/zolana/zopro-keys.lock");for case in cases.values(){let stem=Path::new(case["image"].as_str().unwrap()).file_stem().unwrap().to_str().unwrap();let pin=&lock["keys"][format!("{stem}.key")];pins.insert(format!("/keys/{}",pin["file"].as_str().unwrap()),pin["sha256"].as_str().unwrap().into());pins.insert(format!("/gnark-keys/{stem}.key"),pin["key_sha256"].as_str().unwrap().into());}
 let mut prior:BTreeSet<String>=serde_json::from_value(old["prior_proof_sha256"].clone()).unwrap();let inventory=read("/tmp/zopro-ready-arithmetic/proof-inventory.json");for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){prior.insert(h.as_str().unwrap().to_owned());}}assert_eq!(prior.len(),5104);
 let mut tests=BTreeMap::new();for(mode,core)in[("accepted",109),("diagnostic",113)]{for(label,count)in[("field",33),("core",core)]{let tests_json=read(r.join(format!("native/{mode}-{label}/tests.json")));assert_eq!(tests_json["passed_tests"].as_array().unwrap().len(),count);tests.insert(format!("{mode}-{label}"),count);}}
 let manifest=json!({"scope":"Current170-source accepted and unchanged private readiness diagnostic vs pinned Aeglos Sorted. C7a source/clock/coverage limitations in design.md.","parent_image_id":"sha256:0b79be0b9b5b9675622282a950bd87c8bb98ed092a6605c3a1cb426f6848e66b","container_pins":pins,"prior_proof_sha256":prior,"environment":a["environment"],"cases":cases,"symbol_categories":old["symbol_categories"],"tests":tests,"accepted_manifest_sha256":hash("/tmp/zopro-grouping-module/production-source-manifest.json"),"build_pins_sha256":hash(r.join("build-pins.json")),"rustflags":a["rustflags"].as_str().unwrap().replace("target-cpu=native","target-cpu=znver4"),"new_algorithm":false,"adopted":false});save(c.join("manifest.json"),&manifest);
 fs::write(c.join("Dockerfile"),"FROM 558215002830.dkr.ecr.eu-north-1.amazonaws.com/zolana-prover:bench-latest-c7a-profile-20261025\nCOPY ready-accepted ready-diagnostic ready-adapter ready-runner ready-xtask gnark-verify /usr/local/bin/\nCOPY zopro-keys.lock /manifest/zopro-keys.lock\nCOPY basis /ready-basis\nCOPY manifest.json /ready/manifest.json\nENTRYPOINT [\"/usr/local/bin/ready-runner\"]\n").unwrap();
 let inspected=Command::new("docker").args(["image","inspect","558215002830.dkr.ecr.eu-north-1.amazonaws.com/zolana-prover:bench-latest-c7a-profile-20261025","--format","{{.Id}}"] ).output().unwrap();assert!(inspected.status.success());assert_eq!(String::from_utf8(inspected.stdout).unwrap().trim(),manifest["parent_image_id"].as_str().unwrap());
 let log=fs::File::create(r.join("docker-build.log")).unwrap();let err=log.try_clone().unwrap();assert!(Command::new("docker").args(["build","--pull=false","-t","zopro-ready-c7a:preflight"]).arg(&c).stdout(Stdio::from(log)).stderr(Stdio::from(err)).status().unwrap().success());save(r.join("image-prepared.json"),&json!({"status":"built; not published or launched","container_pins":pins.len(),"source_manifest":manifest,"SDK_targets":"znver4","test_counts":tests}));println!("Exact preflight container built; current clean+diagnostic tests validated, no cloud resources");}
